/// Use this instead of raw Uuid for type safety across modules.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct SessionTagId(pub Uuid);

impl SessionTagId {
    pub fn new(id: Uuid) -> Self {
        Self(id)
    }

    pub fn into_inner(self) -> Uuid {
        self.0
    }
}

impl From<Uuid> for SessionTagId {
    fn from(id: Uuid) -> Self {
        Self(id)
    }
}

impl From<SessionTagId> for Uuid {
    fn from(id: SessionTagId) -> Self {
        id.0
    }
}

/// Data transfer object for SessionTag
///
/// This is the public representation of SessionTag for other modules.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SessionTagDto {
    pub id: SessionTagId,
    pub session_id: Uuid,
    pub tag_id: Uuid,
    pub metadata: serde_json::Value,
}

/// Summary view of SessionTag for list displays
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SessionTagSummary {
    pub id: SessionTagId,
}

/// Reference to SessionTag for foreign key relationships
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SessionTagRef {
    pub id: SessionTagId,
}

